"use client";
import { useCallback, useEffect, useMemo, useState } from "react";
import { AppShell } from "../ui/app-shell";
import { getSupabaseBrowserClient } from "../../lib/supabase/client";
import { usePlayerData } from "../../lib/use-player-data";
type Player = { id: string; display_name: string | null; email: string };
type Week = { id: string; week_number: number; phase: string; focus: string };
type Item = {
  code: string;
  title: string;
  purpose: string;
  setup: string | null;
  instructions: string | null;
  intention: string | null;
  dosage: string | null;
  pass_criterion: string | null;
  equipment: string | null;
  progression: string | null;
  regression: string | null;
  instruction_complete: boolean;
};
type Block = {
  id: string;
  sequence: number;
  domain: string;
  stage: string;
  minutes: number;
  instructions: string | null;
  library_items: Item | null;
};
type Review = {
  session_log_id: string;
  decision: "keep" | "progress" | "modify" | "stop";
  feedback: string;
  evidence_note: string | null;
};
type Log = {
  id: string;
  readiness: number | null;
  energy: number | null;
  soreness: number | null;
  stress: number | null;
  pain_level: number;
  pain_location: string | null;
  state: string | null;
  safety_status: string;
  completion_status: string;
  actual_minutes: number | null;
  session_rpe: number | null;
  session_load: number;
  player_notes: string | null;
  block_completions: Array<{
    id: string;
    session_block_id: string;
    completed: boolean;
  }>;
  session_reviews: Review[];
};
type Session = {
  id: string;
  session_number: number;
  title: string;
  scheduled_day: string | null;
  objective: string | null;
  session_blocks: Block[];
  session_logs: Log[];
};
const blank = {
  readiness: 3,
  energy: 3,
  soreness: 3,
  stress: 3,
  pain_level: 0,
  pain_location: "",
  completion_status: "not_started",
  actual_minutes: 0,
  session_rpe: 5,
  player_notes: "",
};
export default function PracticePage() {
  const { profile } = usePlayerData(),
    [players, setPlayers] = useState<Player[]>([]),
    [selectedId, setSelectedId] = useState(""),
    [weeks, setWeeks] = useState<Week[]>([]),
    [weekId, setWeekId] = useState(""),
    [sessions, setSessions] = useState<Session[]>([]),
    [activeId, setActiveId] = useState(""),
    [form, setForm] = useState(blank),
    [decision, setDecision] = useState<Review["decision"]>("keep"),
    [feedback, setFeedback] = useState(""),
    [evidence, setEvidence] = useState(""),
    [message, setMessage] = useState("");
  const canCoach = profile?.role === "coach" || profile?.role === "admin",
    targetId = canCoach ? selectedId : profile?.id || "";
  const loadPlayers = useCallback(async () => {
    const sb = getSupabaseBrowserClient();
    if (!sb || !profile || !canCoach) return;
    const { data: links } = await sb
      .from("coach_player_links")
      .select("player_id")
      .eq("coach_id", profile.id);
    const ids = (links || []).map((x) => x.player_id);
    if (!ids.length) return;
    const { data } = await sb
      .from("profiles")
      .select("id,display_name,email")
      .in("id", ids);
    const rows = (data || []) as Player[];
    setPlayers(rows);
    setSelectedId((current) => current || rows[0]?.id || "");
  }, [profile, canCoach]);
  const loadWeeks = useCallback(async () => {
    const sb = getSupabaseBrowserClient();
    if (!sb || !targetId) return;
    const { data: p } = await sb
      .from("programmes")
      .select("id")
      .eq("player_id", targetId)
      .in("status", ["published", "completed"])
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (!p) {
      setWeeks([]);
      return;
    }
    const { data } = await sb
      .from("programme_weeks")
      .select("id,week_number,phase,focus")
      .eq("programme_id", p.id)
      .in("status", ["published", "completed"])
      .order("week_number");
    const rows = (data || []) as Week[];
    setWeeks(rows);
    setWeekId((current) =>
      current && rows.some((w) => w.id === current)
        ? current
        : rows[0]?.id || "",
    );
  }, [targetId]);
  const loadSessions = useCallback(async () => {
    const sb = getSupabaseBrowserClient();
    if (!sb || !weekId || !targetId) return;
    const { data, error } = await sb
      .from("programme_sessions")
      .select(
        "id,session_number,title,scheduled_day,objective,session_blocks(id,sequence,domain,stage,minutes,instructions,library_items(code,title,purpose,setup,instructions,intention,dosage,pass_criterion,equipment,progression,regression,instruction_complete)),session_logs!left(id,readiness,energy,soreness,stress,pain_level,pain_location,state,safety_status,completion_status,actual_minutes,session_rpe,session_load,player_notes,block_completions(id,session_block_id,completed))",
      )
      .eq("programme_week_id", weekId)
      .eq("session_logs.player_id", targetId)
      .order("session_number");
    if (error) {
      setMessage(error.message);
      return;
    }
    const rows = (data || []) as unknown as Session[],
      logIds = rows
        .flatMap((session) => session.session_logs || [])
        .map((entry) => entry.id);
    let reviews: Review[] = [];
    if (logIds.length) {
      const { data: reviewRows, error: reviewError } = await sb
        .from("session_reviews")
        .select("session_log_id,decision,feedback,evidence_note")
        .in("session_log_id", logIds);
      if (reviewError) {
        setMessage(
          `Sessions loaded, but coach feedback could not be loaded: ${reviewError.message}`,
        );
      } else reviews = (reviewRows || []) as Review[];
    }
    const byLog = new Map(reviews.map((item) => [item.session_log_id, item]));
    for (const session of rows)
      for (const entry of session.session_logs || [])
        entry.session_reviews = byLog.has(entry.id)
          ? [byLog.get(entry.id)!]
          : [];
    setSessions(rows);
    setActiveId((current) =>
      current && rows.some((session) => session.id === current)
        ? current
        : rows[0]?.id || "",
    );
  }, [weekId, targetId]);
  useEffect(() => {
    const t = setTimeout(() => void loadPlayers(), 0);
    return () => clearTimeout(t);
  }, [loadPlayers]);
  useEffect(() => {
    const t = setTimeout(() => void loadWeeks(), 0);
    return () => clearTimeout(t);
  }, [loadWeeks]);
  useEffect(() => {
    const t = setTimeout(() => void loadSessions(), 0);
    return () => clearTimeout(t);
  }, [loadSessions]);
  const active = sessions.find((s) => s.id === activeId),
    log = active?.session_logs?.[0];
  useEffect(() => {
    if (!active) return;
    const x = active.session_logs?.[0],
      saved = x?.session_reviews?.[0];
    const t = setTimeout(() => {
      setForm(
        x
          ? {
              readiness: x.readiness || 3,
              energy: x.energy || 3,
              soreness: x.soreness || 3,
              stress: x.stress || 3,
              pain_level: x.pain_level,
              pain_location: x.pain_location || "",
              completion_status: x.completion_status,
              actual_minutes: x.actual_minutes || 0,
              session_rpe: x.session_rpe || 5,
              player_notes: x.player_notes || "",
            }
          : blank,
      );
      setDecision(saved?.decision || "keep");
      setFeedback(saved?.feedback || "");
      setEvidence(saved?.evidence_note || "");
    }, 0);
    return () => clearTimeout(t);
  }, [active]);
  const adherence = useMemo(() => {
    const logs = sessions
        .map((s) => s.session_logs?.[0])
        .filter(Boolean) as Log[],
      planned = sessions
        .flatMap((s) => s.session_blocks || [])
        .reduce((n, b) => n + b.minutes, 0),
      actual = logs.reduce((n, l) => n + (l.actual_minutes || 0), 0);
    return {
      planned,
      actual,
      completed: logs.filter((l) => l.completion_status === "completed").length,
      load: logs.reduce((n, l) => n + (l.session_load || 0), 0),
      percent: planned ? Math.round((actual / planned) * 100) : 0,
    };
  }, [sessions]);
  const begin = async (session: Session) => {
    const sb = getSupabaseBrowserClient();
    if (!sb || !profile) return;
    const { error } = await sb
      .from("session_logs")
      .upsert(
        {
          session_id: session.id,
          player_id: profile.id,
          ...form,
          completion_status: "not_started",
          started_at: new Date().toISOString(),
        },
        { onConflict: "session_id,player_id" },
      );
    setMessage(
      error
        ? error.message
        : "Readiness recorded. Follow the released blocks in order.",
    );
    if (!error) await loadSessions();
  };
  const toggleBlock = async (blockId: string) => {
    const sb = getSupabaseBrowserClient();
    if (!sb || !log) return;
    const current = log.block_completions?.find(
        (x) => x.session_block_id === blockId,
      ),
      completed = !current?.completed;
    const { error } = await sb
      .from("block_completions")
      .upsert(
        {
          session_log_id: log.id,
          session_block_id: blockId,
          completed,
          completed_at: completed ? new Date().toISOString() : null,
        },
        { onConflict: "session_log_id,session_block_id" },
      );
    setMessage(error ? error.message : "Block progress saved.");
    if (!error) await loadSessions();
  };
  const finish = async (status: "completed" | "partial" | "stopped") => {
    const sb = getSupabaseBrowserClient();
    if (!sb || !log) return;
    const { error } = await sb
      .from("session_logs")
      .update({
        ...form,
        completion_status: status,
        completed_at: new Date().toISOString(),
      })
      .eq("id", log.id);
    setMessage(
      error
        ? error.message
        : status === "completed"
          ? "Session complete. Your coach can now review the response."
          : "Session response saved for coach review.",
    );
    if (!error) await loadSessions();
  };
  const review = async () => {
    const sb = getSupabaseBrowserClient();
    if (!sb || !profile || !log) return;
    const { error } = await sb
      .from("session_reviews")
      .upsert(
        {
          session_log_id: log.id,
          coach_id: profile.id,
          decision,
          feedback,
          evidence_note: evidence,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "session_log_id" },
      );
    setMessage(error ? error.message : "Coach feedback published.");
    if (!error) await loadSessions();
  };
  return (
    <AppShell active="practice">
      <header className="page-heading">
        <div>
          <p className="eyebrow">Package 7F.3 · Delivery &amp; feedback</p>
          <h1>Train, record, adjust.</h1>
          <p>
            Complete the assigned work, record readiness and session load, and
            let repeated evidence—not one unusual day—guide the next decision.
          </p>
        </div>
      </header>
      {message && (
        <div className="success-banner" role="status">
          {message}
        </div>
      )}
      {canCoach && (
        <section className="delivery-player">
          <label>
            Review player
            <select
              value={selectedId}
              onChange={(e) => setSelectedId(e.target.value)}
            >
              {players.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.display_name || p.email}
                </option>
              ))}
            </select>
          </label>
        </section>
      )}
      <section className="delivery-summary">
        <div>
          <span>Adherence</span>
          <strong>{adherence.percent}%</strong>
        </div>
        <div>
          <span>Minutes</span>
          <strong>
            {adherence.actual}/{adherence.planned}
          </strong>
        </div>
        <div>
          <span>Sessions</span>
          <strong>
            {adherence.completed}/{sessions.length}
          </strong>
        </div>
        <div>
          <span>Session load</span>
          <strong>{adherence.load}</strong>
        </div>
      </section>
      <nav className="delivery-weeks">
        {weeks.map((w) => (
          <button
            className={w.id === weekId ? "active" : ""}
            onClick={() => {
              setWeekId(w.id);
              setActiveId("");
            }}
            key={w.id}
          >
            Week {w.week_number}
            <small>{w.phase}</small>
          </button>
        ))}
      </nav>
      <div className="delivery-grid">
        <section className="delivery-list">
          {sessions.map((session) => {
            const entry = session.session_logs?.[0];
            return (
              <button
                className={activeId === session.id ? "active" : ""}
                onClick={() => setActiveId(session.id)}
                key={session.id}
              >
                <span>0{session.session_number}</span>
                <div>
                  <strong>{session.title}</strong>
                  <small>
                    {session.scheduled_day || "Flexible day"} ·{" "}
                    {session.session_blocks.reduce((n, b) => n + b.minutes, 0)}{" "}
                    min
                  </small>
                </div>
                <b className={entry?.safety_status || "clear"}>
                  {entry?.completion_status || "Ready"}
                </b>
              </button>
            );
          })}
          {!sessions.length && (
            <div className="empty-state compact">
              <h2>No released sessions</h2>
              <p>
                Your coach must release a reconciled week before sessions
                appear.
              </p>
            </div>
          )}
        </section>
        {active && (
          <section className="delivery-detail">
            <header>
              <p className="eyebrow">Session {active.session_number}</p>
              <h2>{active.title}</h2>
              <p>{active.objective}</p>
            </header>
            {!canCoach && !log && (
              <form
                className="readiness-form"
                onSubmit={(e) => {
                  e.preventDefault();
                  void begin(active);
                }}
              >
                <h3>Before you start</h3>
                {[
                  ["readiness", "Readiness"],
                  ["energy", "Energy"],
                  ["soreness", "Soreness"],
                  ["stress", "Stress"],
                ].map(([key, label]) => (
                  <label key={key}>
                    {label}
                    <input
                      type="range"
                      min="1"
                      max="5"
                      value={form[key as keyof typeof form] as number}
                      onChange={(e) =>
                        setForm({ ...form, [key]: Number(e.target.value) })
                      }
                    />
                    <b>{form[key as keyof typeof form]}</b>
                  </label>
                ))}
                <label>
                  Pain level (0–10)
                  <input
                    type="number"
                    min="0"
                    max="10"
                    value={form.pain_level}
                    onChange={(e) =>
                      setForm({ ...form, pain_level: Number(e.target.value) })
                    }
                  />
                </label>
                {form.pain_level > 0 && (
                  <label>
                    Pain location
                    <input
                      value={form.pain_location}
                      onChange={(e) =>
                        setForm({ ...form, pain_location: e.target.value })
                      }
                    />
                  </label>
                )}
                <button className="primary-action">
                  Save check-in and begin
                </button>
              </form>
            )}
            {log && (
              <>
                <div className={`response-state ${log.safety_status}`}>
                  <strong>{log.state}</strong>
                  <span>
                    {log.safety_status === "stop_and_review"
                      ? "Stop this session and contact your coach. This is a safety flag, not a diagnosis."
                      : log.safety_status === "monitor"
                        ? "Modify intensity if needed and record the response for your coach."
                        : "No readiness stop flag recorded."}
                  </span>
                </div>
                <div className="delivery-blocks">
                  {active.session_blocks
                    .sort((a, b) => a.sequence - b.sequence)
                    .map((block) => {
                      const done = log.block_completions?.some(
                        (x) => x.session_block_id === block.id && x.completed,
                      );
                      return (
                        <article className={done ? "done" : ""} key={block.id}>
                          <span>{block.stage}</span>
                          <div>
                            <h3>{block.library_items?.title}</h3>
                            <small>
                              {block.library_items?.dosage} · {block.minutes}{" "}
                              min
                            </small>
                            {block.instructions && (
                              <p className="coach-block-note">
                                <b>Coach instruction</b>
                                {block.instructions}
                              </p>
                            )}
                            {block.library_items?.instruction_complete ? (
                              <details className="player-block-instructions" open>
                                <summary>How to perform this {block.domain === "vector" ? "movement" : "drill"}</summary>
                                <dl>
                                  <div><dt>Purpose</dt><dd>{block.library_items.purpose}</dd></div>
                                  <div><dt>Setup</dt><dd>{block.library_items.setup}</dd></div>
                                  {block.library_items.equipment && <div><dt>Equipment</dt><dd>{block.library_items.equipment}</dd></div>}
                                  <div><dt>What to do</dt><dd className="preserve-lines">{block.library_items.instructions}</dd></div>
                                  {block.library_items.intention && <div><dt>Intention / feel</dt><dd>{block.library_items.intention}</dd></div>}
                                  <div><dt>Dose</dt><dd>{block.library_items.dosage}</dd></div>
                                  <div><dt>Success check</dt><dd>{block.library_items.pass_criterion}</dd></div>
                                  {block.library_items.progression && <div><dt>Progression</dt><dd>{block.library_items.progression}</dd></div>}
                                  {block.library_items.regression && <div><dt>Regression</dt><dd>{block.library_items.regression}</dd></div>}
                                </dl>
                              </details>
                            ) : (
                              <p className="instruction-pending">Full instructions are being prepared by your coach.</p>
                            )}
                          </div>
                          {!canCoach && (
                            <button onClick={() => toggleBlock(block.id)}>
                              {done ? "Completed ✓" : "Mark complete"}
                            </button>
                          )}
                        </article>
                      );
                    })}
                </div>
                {!canCoach && (
                  <section className="finish-form">
                    <label>
                      Actual minutes
                      <input
                        type="number"
                        min="0"
                        value={form.actual_minutes}
                        onChange={(e) =>
                          setForm({
                            ...form,
                            actual_minutes: Number(e.target.value),
                          })
                        }
                      />
                    </label>
                    <label>
                      Session RPE (1–10)
                      <input
                        type="number"
                        min="1"
                        max="10"
                        value={form.session_rpe}
                        onChange={(e) =>
                          setForm({
                            ...form,
                            session_rpe: Number(e.target.value),
                          })
                        }
                      />
                    </label>
                    <label className="wide">
                      Player notes
                      <textarea
                        value={form.player_notes}
                        onChange={(e) =>
                          setForm({ ...form, player_notes: e.target.value })
                        }
                      />
                    </label>
                    <div>
                      <button onClick={() => finish("stopped")}>Stop</button>
                      <button onClick={() => finish("partial")}>
                        Save partial
                      </button>
                      <button
                        className="primary-action"
                        onClick={() => finish("completed")}
                      >
                        Complete session
                      </button>
                    </div>
                  </section>
                )}
                {canCoach && (
                  <section className="coach-response">
                    <div className="load-strip">
                      <span>{log.state}</span>
                      <b>RPE {log.session_rpe || "—"}</b>
                      <b>{log.actual_minutes || 0} min</b>
                      <b>Load {log.session_load || 0}</b>
                    </div>
                    <p>{log.player_notes || "No player note."}</p>
                    <label>
                      Decision
                      <select
                        value={decision}
                        onChange={(e) =>
                          setDecision(e.target.value as Review["decision"])
                        }
                      >
                        <option value="keep">Keep</option>
                        <option value="progress">Progress</option>
                        <option value="modify">Modify</option>
                        <option value="stop">Stop</option>
                      </select>
                    </label>
                    <label>
                      Coach feedback
                      <textarea
                        value={feedback}
                        onChange={(e) => setFeedback(e.target.value)}
                        required
                      />
                    </label>
                    <label>
                      Evidence supporting decision
                      <textarea
                        value={evidence}
                        onChange={(e) => setEvidence(e.target.value)}
                      />
                    </label>
                    <button
                      className="primary-action"
                      onClick={review}
                      disabled={!feedback}
                    >
                      Publish feedback
                    </button>
                  </section>
                )}
                {!canCoach && log.session_reviews?.[0] && (
                  <section className="published-feedback">
                    <p className="eyebrow">
                      Coach decision · {log.session_reviews[0].decision}
                    </p>
                    <h3>{log.session_reviews[0].feedback}</h3>
                    {log.session_reviews[0].evidence_note && (
                      <p>{log.session_reviews[0].evidence_note}</p>
                    )}
                  </section>
                )}
              </>
            )}
          </section>
        )}
      </div>
    </AppShell>
  );
}
